"use strict";
/* =====================================================================
   Choix du monde : vignettes, vue aérienne du tracé et arrivée animée
   ===================================================================== */
/* ---------- Virages des mondes fabriqués ----------
   Le tracé est une suite de lignes droites et d'arcs de cercle (morceaux [longueur, courbure], courbure = 1/rayon, + = à droite),
   tirés au hasard avec une graine fixe (le même tracé à chaque fois). On en tire une table du cap (direction de la route, en radians)
   mètre par mètre : route.virages, que le monde 3D suit. Dans les grandes pentes, des lacets : lignes droites reliées par des épingles. */
function aleaGraine(g) { let s = g >>> 0; return () => { s = (Math.imul(s, 1664525) + 1013904223) >>> 0; return s / 4294967296; }; }
function tableCap(L, morceaux) {
  const n = Math.ceil(L) + 2, k = new Float64Array(n + 1);
  let d = 0;
  for (const [l, c] of morceaux) { const a = Math.round(d), b = Math.min(n, Math.round(d + l)); for (let i = a; i < b; i++) k[i] = c; d += l; }
  // courbure adoucie sur 16 m : on entre et on sort des virages progressivement (le total de chaque virage est conservé)
  const cumul = new Float64Array(n + 2);
  for (let i = 0; i <= n; i++) cumul[i + 1] = cumul[i] + k[i];
  const cap = new Float32Array(n);
  let h = 0;
  for (let i = 0; i < n; i++) {
    cap[i] = h;
    const a = Math.max(0, i - 8), b = Math.min(n, i + 8);
    h += (cumul[b + 1] - cumul[a]) / (b - a + 1);
  }
  return cap;
}
// o : graine, droit [min, max] (m), rayon [min, max] (m), angle [min, max] (degrés), capMax (degrés : écart maximal à la direction générale),
// lacets : [[début, fin], …] zones en lacets, rayonGauche : rayon minimal des virages à gauche, calme(d) : 0 à 1 (1 = virages adoucis, en ville)
function tracerVirages(r, o) {
  const rand = aleaGraine(o.graine), m = [], PI = Math.PI, L = r.longueur, capMax = o.capMax * PI / 180, epingles = [];
  let d = 0, cap = 0;
  const droit = (l) => { if (l > 0) { m.push([l, 0]); d += l; } };
  const arc = (R, angle) => { const l = Math.abs(angle) * R; m.push([l, Math.sign(angle) / R]); d += l; cap += angle; };
  function lacets(fin) {
    const Re = 38, R = 15 + rand() * 7, tours = fin - d - 240 - PI * Re;
    if (tours < 700) { droit(fin - d); return; }
    const s = rand() < 0.5 ? 1 : -1;                 // les lacets partent à droite ou à gauche, perpendiculaires à la route
    const n = Math.max(2, Math.floor((tours + PI * R) / (330 + PI * R))), branche = (tours - (n - 1) * PI * R) / n;
    // branches de longueurs variées (même total) : des lacets moins réguliers
    const fac = []; let somme = 0;
    for (let k = 0; k < n; k++) { fac.push(0.75 + 0.5 * rand()); somme += fac[k]; }
    droit(120); arc(Re, s * PI / 2);
    for (let k = 1; k <= n; k++) {
      droit(branche * fac[k - 1] * n / somme);
      if (k < n) { epingles.push(d + PI * R / 2); arc(R, s * PI * (k % 2 ? -1 : 1)); }
    }
    arc(Re, (n % 2 ? -1 : 1) * s * PI / 2);
    droit(fin - d);
  }
  droit(220);                                         // départ en ligne droite (arche)
  const zones = (o.lacets || []).slice();
  while (d < L) {
    const z = zones[0];
    if (z && d >= z[0] - 1) { zones.shift(); lacets(z[1]); continue; }
    const limite = z ? z[0] : L + 1, calme = o.calme ? o.calme(d) : 0;
    const ls = o.droit[0] + rand() * (o.droit[1] - o.droit[0]) * (1 + calme);
    let R = (o.rayon[0] + Math.pow(rand(), 1.3) * (o.rayon[1] - o.rayon[0])) * (1 + 1.5 * calme);
    let a = (o.angle[0] + rand() * (o.angle[1] - o.angle[0])) * (1 - 0.6 * calme) * PI / 180;
    let sg = rand() < 0.5 ? -1 : 1;
    if (Math.abs(cap) > capMax * 0.4 && rand() < 0.75) sg = -Math.sign(cap);   // on revient vers la direction générale
    if (Math.abs(cap + sg * a) > capMax) a = Math.max(0, capMax - sg * cap);
    if (a < 0.08) { sg = -sg; a = Math.min(0.3, capMax + Math.abs(cap)); }
    if (sg < 0 && o.rayonGauche) R = Math.max(R, o.rayonGauche);
    if (d + ls + a * R > limite) { droit(limite - d); continue; }
    droit(ls); arc(R, sg * a);
  }
  r.virages = tableCap(L + 60, m);
  if (o.boucle) fermerBoucle(r, o.boucle);
  // épingles numérotées comme dans les grands cols : le compte à rebours finit à 1 près du sommet
  r.epingles = epingles.filter((e) => e < L).map((e, i, t) => ({ d: e, n: t.length - i }));
  return r;
}
// boucle : on ajoute exactement un tour complet (sens = 1 : à droite, sens horaire), réparti sur toute la distance, puis on corrige
// le tracé (deux ondulations très lentes, nulles au départ et à l'arrivée) pour que l'arrivée retombe exactement sur le départ
function fermerBoucle(r, sens) {
  const L = Math.round(r.longueur), t0 = r.virages, c = new Float64Array(L + 1), PI2 = 2 * Math.PI;
  for (let i = 0; i <= L; i++) c[i] = t0[i] + (PI2 * sens - t0[L]) * i / L;
  const bout = (a, b) => {
    let x = 0, z = 0;
    for (let i = 0; i < L; i++) {
      const w = PI2 * (i + 0.5) / L, h = (c[i] + c[i + 1]) / 2 + a * Math.sin(w) + b * (Math.cos(w) - 1);
      x += Math.sin(h); z -= Math.cos(h);
    }
    return [x, z];
  };
  let a = 0, b = 0;
  for (let it = 0; it < 15; it++) {                  // méthode de Newton sur (a, b) : écart d'arrivée nul
    const f = bout(a, b);
    if (Math.hypot(f[0], f[1]) < 0.3) break;
    const e = 1e-4, fa = bout(a + e, b), fb = bout(a, b + e);
    const j11 = (fa[0] - f[0]) / e, j21 = (fa[1] - f[1]) / e, j12 = (fb[0] - f[0]) / e, j22 = (fb[1] - f[1]) / e, det = j11 * j22 - j12 * j21;
    if (Math.abs(det) < 1e-9) break;
    let da = -(j22 * f[0] - j12 * f[1]) / det, db = -(-j21 * f[0] + j11 * f[1]) / det;
    const n = Math.hypot(da, db);
    if (n > 0.4) { da *= 0.4 / n; db *= 0.4 / n; }
    a += da; b += db;
  }
  const t = new Float32Array(L + 2);
  for (let i = 0; i <= L + 1; i++) { const j = Math.min(i, L), w = PI2 * j / L; t[i] = c[j] + a * Math.sin(w) + b * (Math.cos(w) - 1); }
  r.virages = t; r.tourCap = PI2 * sens;
}
// profil d'une boucle : on retouche toutes les pentes du même petit écart pour revenir à l'altitude de départ
function profilBoucle(segments) {
  let L = 0, gain = 0;
  for (const [l, p] of segments) { L += l; gain += l * p / 100; }
  return segments.map(([l, p]) => [l, p - gain / L * 100]);
}
// zones en lacets : les segments du profil assez raides et assez longs
function zonesLacets(r, penteMin, longMin) {
  const z = [];
  let x = 0;
  for (const [l, p] of r.segments) { if (Math.abs(p) >= penteMin && l >= longMin) z.push([x, x + l]); x += l; }
  return z;
}

/* Monde de montagne fabriqué : 60 km, 2 500 m de dénivelé positif, arrivée au sommet */
function routeAlpes() {
  const base = [[1000, 0.5], [2000, 1], [2000, 3],
    [3000, 5.5], [3000, 7.5], [2500, 6.5], [500, 9],
    [1500, -1], [3500, -6.5], [1000, -3],
    [2000, 3.5], [1500, -2], [2500, 4.5],
    [3000, 6], [3000, 8], [3000, 7], [2000, 9], [1000, 6.5],
    [3000, -7], [3500, -6], [2000, -4],
    [1500, 2], [1000, -1.5], [1500, 3.5],
    [2500, 7], [2500, 8.5], [2000, 9], [1500, 7.5], [1000, 10]];
  let brut = 0;
  for (const [l, p] of base) if (p > 0) brut += l * p / 100;
  const f = 2500 / brut;
  const r = construireRoute("Grand Col des Alpes", base.map(([l, p]) => [l, p > 0 ? p * f : p]), false, 650);
  r.alpes = true; r.synth = true;
  // route de montagne sinueuse, lacets dans les passages raides (montées et descentes)
  return tracerVirages(r, { graine: 7341, droit: [30, 260], rayon: [60, 340], angle: [20, 85], capMax: 75, lacets: zonesLacets(r, 6.5, 1500) });
}
/* Monde du bord de mer : boucle de 30 km quasi plate autour d’une île, cinq villes, la mer à gauche (à l’extérieur) */
function routeMer() {
  const g = [0.2, -0.1, 0.3, -0.2, 0.1, 0.4, -0.3, 0.1, -0.2, 0.2, -0.1, 0.3, -0.2, 0.2, -0.3, 0.1, 0.2, -0.2, 0.1, -0.1];
  const r = construireRoute("Corniche Bleue", profilBoucle(g.map((p) => [1500, p])), true, 4);
  r.mer = true; r.synth = true;
  r.villes = [[2600, 4300, "Port-Soleil"], [8400, 10000, "Saint-Azur"], [14300, 16200, "La Marine"], [20300, 21900, "Cap-Sable"], [26400, 28400, "Belle-Plage"]];
  // corniche : virages qui suivent la côte (plus doux vers la mer, à gauche, et dans les villes)
  return tracerVirages(r, { graine: 2207, droit: [80, 520], rayon: [130, 520], angle: [12, 55], capMax: 50, rayonGauche: 260, boucle: 1,
    calme: (d) => r.villes.some((v) => d > v[0] - 200 && d < v[1] + 200) ? 1 : 0 });
}
/* Monde du désert : boucle de 20 km de collines de sable et de pistes vallonnées */
function routeDesert() {
  const base = [[1000, 1], [1200, 4], [900, 6.5], [1100, -3], [1500, -5.5], [800, 2], [1300, 5], [1000, 7], [700, -1], [1600, -6],
    [1200, -2], [1000, 3.5], [1400, 5.5], [900, 8], [800, -4], [1700, -6.5], [1100, 2.5], [1300, 4.5], [1000, -3.5], [1400, -3]];
  let tot = 0;
  for (const [l] of base) tot += l;
  const r = construireRoute("Piste des Dunes", profilBoucle(base.map(([l, p]) => [l * 20000 / tot, p])), true, 180);
  r.desert = true; r.synth = true;
  // piste qui serpente entre les dunes
  return tracerVirages(r, { graine: 9917, droit: [40, 320], rayon: [70, 320], angle: [25, 110], capMax: 80, boucle: -1 });
}
/* Mondes Triathlon : un décor par format, inspiré d'un triathlon célèbre (XS désert de Dubaï, S Côte d'Azur de Nice, M île de Lanzarote,
   L campagne de Roth, XXL Kona à Hawaï). Boucles (la mer à gauche quand il y en a une), longues lignes droites et grandes courbes,
   faux plats et bosses, départ dans le premier village, ravitaillement tous les 5 km (route.triathlon) */
const DECORS_TRI = {
  desert: ["Al Qudra", "Bab Al Shams", "Lahbab", "Margham"],
  mer: ["Nice", "Villefranche", "Beaulieu", "Èze", "Cap-d'Ail"],
  lanzarote: ["Puerto del Carmen", "La Geria", "Yaiza", "Teguise", "Haría"],
  campagne: ["Roth", "Hilpoltstein", "Eckersmühlen", "Greding", "Büchenbach"],
  kona: ["Kailua-Kona", "Waikoloa", "Kawaihae", "Hawi", "Puakō", "Keauhou", "Kohala", "Hōlualoa", "Kapa'au"]
};
function routeTriathlon(nom, km, graine, dplus, decor) {
  decor = decor || "kona";
  const L = km * 1000, rand = aleaGraine(graine), seg = [];
  let x = 0;
  while (x < L - 1) {
    const l = Math.min(L - x, 400 + rand() * 1500);
    seg.push([l, (rand() - 0.5) * 2 * (rand() < 0.3 ? 3 : 1.5)]); x += l;
  }
  // dénivelé visé : la boucle est d'abord refermée (retour à l'altitude de départ), puis toutes les pentes sont mises à l'échelle
  let prof = profilBoucle(seg);
  for (let it = 0; it < 3; it++) {
    let gain = 0;
    for (const [l, p] of prof) if (p > 0) gain += l * p / 100;
    const f = dplus / Math.max(1, gain);
    prof = profilBoucle(prof.map(([l, p]) => [l, Math.max(-5, Math.min(5, p * f))]));
  }
  const r = construireRoute(nom, prof, true, 25);
  r.synth = true; r.triathlon = true; r.decor = decor;
  if (decor === "mer" || decor === "kona" || decor === "lanzarote") r.mer = true;
  if (decor === "desert") r.desert = true;
  const noms = DECORS_TRI[decor] || DECORS_TRI.kona, n = Math.max(1, Math.round(km / 30));
  r.villes = [[150, 1500, noms[0]]];
  for (let i = 1; i <= n; i++) { const c = L * i / (n + 1); r.villes.push([c - 600, c + 600, noms[1 + (i - 1) % (noms.length - 1)]]); }
  return tracerVirages(r, { graine, droit: [250, 1500], rayon: [350, 1100], angle: [8, 32], capMax: 45, rayonGauche: 450, boucle: 1,
    calme: (d) => r.villes.some((v) => d > v[0] - 200 && d < v[1] + 200) ? 1 : 0 });
}
/* Monde des Ardennes : boucle de 25 km en forêt, huit côtes courtes et raides (6 à 12 %) séparées par des descentes et des fonds de vallée,
   villages de pierre (route.villes) et côtes nommées (route.cotes, affichées dans le HUD) ; environ 500 m de D+ */
function routeArdennes() {
  const base = [[1300, 0.5], [900, 7], [300, 4], [1500, -4.5], [1000, 1], [1000, 6], [1200, -5], [900, 0.5], [450, 11], [400, 3], [1400, -4.5],
    [800, 1.5], [800, 8], [1300, -5], [700, 0.5], [600, 9.5], [1100, -4], [1000, 0.5], [500, 10.5], [1200, -4.5], [700, 8.5], [1100, -5.5],
    [800, 1], [400, 12], [1500, -4.5], [2150, -0.5]];
  const r = construireRoute("Boucle des Ardennes", profilBoucle(base), true, 230);
  r.synth = true; r.ardennes = true;
  r.villes = [[100, 1300, "Bouillon"], [7150, 8100, "Rochehaut"], [15600, 16650, "Vresse-sur-Semois"], [24150, 24990, "Bouillon"]];
  r.cotes = [[1300, 2500, "Côte du Château"], [5000, 6000, "Côte de Corbion"], [8100, 8950, "Mur de Rochehaut"], [11150, 11950, "Côte de Laviot"],
    [13950, 14550, "Côte d'Alle"], [16650, 17150, "Côte de Vresse"], [18350, 19050, "Côte de Membre"], [20950, 21350, "Mur de Frahan"]];
  // petite route forestière sinueuse, virages plus doux dans les villages
  return tracerVirages(r, { graine: 6113, droit: [40, 280], rayon: [55, 240], angle: [20, 95], capMax: 75, boucle: 1,
    calme: (d) => r.villes.some((v) => d > v[0] - 200 && d < v[1] + 200) ? 1 : 0 });
}
