  if (L - m * 20 > 1) { gd.push(L); ga.push(el[N - 1]); }
  const gl = ga.map((_, k) => { let s = 0, c = 0; for (let q = k - 3; q <= k + 3; q++) if (q >= 0 && q < ga.length) { s += ga[q]; c++; } return s / c; });
