      if (!rep.ok) throw new Error("serveur " + rep.status);
      const j = await rep.json();
      if (!j || !Array.isArray(j.elements)) throw new Error("réponse inattendue");
      // un serveur à court de temps ou de mémoire répond « 200 » avec une remarque et un décor tronqué : on le refuse
      if (j.remark && /error|timed out|out of memory/i.test(j.remark)) throw new Error("réponse incomplète");
